SELECT 'core-2026-09-v4','articles-place-names','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"articles-place-names","title":"Articles with place names and institutions","level":"A2","order":20,"summary":"Learn common geographical patterns and distinguish an institution’s purpose from its physical building.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Names that usually take no article","Names that commonly take the","Institutional purpose and the building","Names inside larger noun phrases"],"rules":[{"title":"Names that usually take no article","explanation":"Most ordinary country and city names take no article, as do continents, individual mountains named with Mount, and lakes named with Lake. These are naming conventions rather than a universal rule for all proper nouns.","pattern":"**France**, **Tokyo**, **Mount Fuji**, **Lake Victoria**","commonMistakes":["The Hague is a city-name exception. Check unfamiliar names rather than guessing solely from the place category."],"examples":["Use ordinary geographical reference to a country with an ordinary short name: “We studied a map of **—** France.” (— = no article)","Use ordinary geographical reference to a country with an ordinary short name: “We studied a map of **—** Japan.” (— = no article)"],"skill":"form"},{"title":"Names that commonly take the","explanation":"River, sea, ocean and mountain-range names commonly take **the**. Some country names also do, especially plural names or names containing words such as Kingdom and Republic. Short and full official names can behave differently.","pattern":"**the Nile**, **the Alps**, **the United Kingdom**","commonMistakes":["Czechia normally has no article; the Czech Republic takes the. The chosen name matters."],"examples":["Complete ordinary naming inside an of-phrase: “The geography of **—** France was our subject.”","Complete ordinary naming inside an of-phrase: “The geography of **—** Japan was our subject.”"],"skill":"meaning"},{"title":"Institutional purpose and the building","explanation":"In British English, go to school, be in prison and be in hospital can refer to the institution’s usual role. The school or the hospital often identifies a particular building or site. American usage differs notably for in the hospital.","pattern":"The pupil is **at school**. / The builder is **at the school**.","commonMistakes":["Do not mark American in the hospital wrong without specifying the variety and intended meaning."],"examples":["Which category explains the ordinary article pattern for “France”? → **a country with an ordinary short name**","Which category explains the ordinary article pattern for “Japan”? → **a country with an ordinary short name**"],"skill":"contrast"},{"title":"Names inside larger noun phrases","explanation":"A geographical name can occur inside a larger noun phrase, where an article may belong to another noun. The history of France has the before history, not before France. A new context can also make a proper name descriptive: the Paris of my childhood.","pattern":"**The history of France** is the subject.","commonMistakes":["The exercises test ordinary geographical reference, not special descriptive or metaphorical uses of names."],"examples":["Choose the ordinary geographical name phrase to complete “Our lesson concerned **France**.” The place is france (a country with an ordinary short name).","Choose the ordinary geographical name phrase to complete “Our lesson concerned **Japan**.” The place is japan (a country with an ordinary short name)."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-zero-articles"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Learn common geographical patterns and distinguish an institution’s purpose from its physical building.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Names that usually take no article","explanation":"Most ordinary country and city names take no article, as do continents, individual mountains named with Mount, and lakes named with Lake. These are naming conventions rather than a universal rule for all proper nouns.","pattern":"**France**, **Tokyo**, **Mount Fuji**, **Lake Victoria**","commonMistakes":["The Hague is a city-name exception. Check unfamiliar names rather than guessing solely from the place category."],"examples":["Use ordinary geographical reference to a country with an ordinary short name: “We studied a map of **—** France.” (— = no article)","Use ordinary geographical reference to a country with an ordinary short name: “We studied a map of **—** Japan.” (— = no article)"],"skill":"form","id":"articles-place-names-foundation-1","domain":"noun-phrases","referenceIds":["bc-zero-articles"],"readingVersion":"core-2026-09-v3"},{"title":"Names that commonly take the","explanation":"River, sea, ocean and mountain-range names commonly take **the**. Some country names also do, especially plural names or names containing words such as Kingdom and Republic. Short and full official names can behave differently.","pattern":"**the Nile**, **the Alps**, **the United Kingdom**","commonMistakes":["Czechia normally has no article; the Czech Republic takes the. The chosen name matters."],"examples":["Complete ordinary naming inside an of-phrase: “The geography of **—** France was our subject.”","Complete ordinary naming inside an of-phrase: “The geography of **—** Japan was our subject.”"],"skill":"meaning","id":"articles-place-names-foundation-2","domain":"noun-phrases","referenceIds":["bc-zero-articles"],"readingVersion":"core-2026-09-v3"},{"title":"Institutional purpose and the building","explanation":"In British English, go to school, be in prison and be in hospital can refer to the institution’s usual role. The school or the hospital often identifies a particular building or site. American usage differs notably for in the hospital.","pattern":"The pupil is **at school**. / The builder is **at the school**.","commonMistakes":["Do not mark American in the hospital wrong without specifying the variety and intended meaning."],"examples":["Which category explains the ordinary article pattern for “France”? → **a country with an ordinary short name**","Which category explains the ordinary article pattern for “Japan”? → **a country with an ordinary short name**"],"skill":"contrast","id":"articles-place-names-foundation-3","domain":"noun-phrases","referenceIds":["bc-zero-articles"],"readingVersion":"core-2026-09-v3"},{"title":"Names inside larger noun phrases","explanation":"A geographical name can occur inside a larger noun phrase, where an article may belong to another noun. The history of France has the before history, not before France. A new context can also make a proper name descriptive: the Paris of my childhood.","pattern":"**The history of France** is the subject.","commonMistakes":["The exercises test ordinary geographical reference, not special descriptive or metaphorical uses of names."],"examples":["Choose the ordinary geographical name phrase to complete “Our lesson concerned **France**.” The place is france (a country with an ordinary short name).","Choose the ordinary geographical name phrase to complete “Our lesson concerned **Japan**.” The place is japan (a country with an ordinary short name)."],"skill":"application","id":"articles-place-names-foundation-4","domain":"noun-phrases","referenceIds":["bc-zero-articles"],"readingVersion":"core-2026-09-v3"},{"domain":"noun-phrases","id":"institutional-articles","title":"Institutional purpose, locations and activities","explanation":"School, prison, church, bed and some other nouns can take no article in established expressions about their usual purpose. The same noun can take the when a particular building or object is meant. Hospital differs notably across British and American usage. These are conventional patterns, so they must be learned individually.","pattern":"at **school** / outside **the school**","examples":["The children are **at school**; their father is **at the school** for a meeting.","She went **to bed** early; the cat hid **under the bed**."],"commonMistakes":["The contrast is not always purpose versus building for every noun. We normally say at university in British English but at the office in both major varieties."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"noun-phrases","id":"article-conventions","title":"Meals, transport, illnesses, languages and titles","explanation":"Many familiar expressions use no article: have breakfast, travel by bus, speak Spanish. Modification, specificity or a count meaning can introduce an article: a large breakfast, the bus we caught. Titles before a personal name often omit the article. Illness names have individual patterns rather than one general rule.","pattern":"by **train** / on **the train**","examples":["We had **breakfast**. / We enjoyed **a late breakfast**.","**Professor Silva** spoke about **the Spanish language**."],"commonMistakes":["A headache and a cold take an article in ordinary use, while flu/the flu varies by variety. Do not extend the meal or transport convention to unrelated nouns."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**France**, **Tokyo**, **Mount Fuji**, **Lake Victoria**","**the Nile**, **the Alps**, **the United Kingdom**","The pupil is **at school**. / The builder is **at the school**.","**The history of France** is the subject."],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["movement-prepositions"],"readingReferenceIds":["bc-zero-articles","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='articles-place-names'
